package mx.com.mesaregia.inventario.api.controller;
import mx.com.mesaregia.inventario.application.service.DisponibilidadService; import mx.com.mesaregia.inventario.api.response.DisponibilidadResponse; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/inventario/disponibilidad") public class DisponibilidadController {private final DisponibilidadService s; public DisponibilidadController(DisponibilidadService s){this.s=s;} @GetMapping @PreAuthorize("hasAuthority('inventario.disponibilidad.consultar')") public DisponibilidadResponse get(@RequestParam Long idProducto,@RequestParam Long idAlmacen,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fechaInicio,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fechaFin,@RequestParam Integer cantidad){return s.consultarFutura(idProducto,idAlmacen,fechaInicio,fechaFin,cantidad);} }
